// Shared term/definition datasets for all PSYC2200 lectures, used by both
// the Learn-mode quiz pages (lectureXX.html + quiz.js) and the matching game (match.html).

const LECTURES = {
  "lecture9-psyc2200": {
    title: "Lecture 9",
    subtitle: "Brain development, evolution, and the spinal cord",
    terms: [
      { term: "Neural plate", def: "The first sign of the nervous system in the embryo — a thickened region of tissue that begins to separate from the rest of the developing embryo." },
      { term: "Neural groove", def: "Formed when the neural plate sinks down (invaginates) and its edges rise up on either side." },
      { term: "Neural tube", def: "Formed when the neural groove closes up into a hollow tube; retains a fluid-filled canal in the center." },
      { term: "Neural crest", def: "A ridge that forms along the length of the neural tube, marking where the spine/backbone will be." },
      { term: "Prosencephalon", def: "The most rostral of the three primary brain vesicles; becomes the forebrain, later splitting into the telencephalon and diencephalon." },
      { term: "Mesencephalon", def: "The middle primary brain vesicle; becomes the midbrain and does not split further." },
      { term: "Rhombencephalon", def: "The most caudal primary brain vesicle; becomes the hindbrain, later splitting into the metencephalon and myelencephalon." },
      { term: "Telencephalon", def: "The most rostral secondary vesicle, derived from the prosencephalon (forebrain)." },
      { term: "Diencephalon", def: "A secondary vesicle derived from the prosencephalon; contains structures such as the hypothalamus." },
      { term: "Metencephalon", def: "A secondary vesicle derived from the rhombencephalon, closer to the midbrain." },
      { term: "Myelencephalon", def: "The most caudal secondary vesicle, derived from the rhombencephalon." },
      { term: "Endocast", def: "A plaster cast of the inside of a fossil skull, used to estimate what an extinct animal's brain looked like." },
      { term: "Adaptation (brain evolution)", def: "The evolutionary elaboration of one or more parts of the same basic brain blueprint to suit an animal's environment and needs." },
      { term: "CNS (Central Nervous System)", def: "The brain and spinal cord." },
      { term: "PNS (Peripheral Nervous System)", def: "Everything in the nervous system except the brain and spinal cord." },
      { term: "Somatic nervous system", def: "The division of the PNS that serves the body (skin and skeletal muscle) — includes sensory and motor components." },
      { term: "Autonomic nervous system", def: "The division of the PNS that controls internal organs/viscera automatically, without conscious control." },
      { term: "Afferent", def: "Sensory information traveling INTO the central nervous system." },
      { term: "Efferent", def: "Motor information traveling OUT of the central nervous system." },
      { term: "Sympathetic nervous system", def: "The autonomic division responsible for arousal ('fight or flight') — increases heart rate, dilates pupils, increases sweating." },
      { term: "Parasympathetic nervous system", def: "The autonomic division responsible for relaxation ('rest and digest') — the opposite of the sympathetic system." },
      { term: "Dorsal", def: "Toward the back." },
      { term: "Ventral", def: "Toward the belly/front." },
      { term: "Rostral", def: "Toward the nose/front." },
      { term: "Caudal", def: "Toward the tail/rear." },
      { term: "Anterior", def: "Toward the front; used interchangeably with ventral in the human body." },
      { term: "Posterior", def: "Toward the back; used interchangeably with dorsal in the human body." },
      { term: "Medial", def: "Toward the midline of the body." },
      { term: "Lateral", def: "Toward the side of the body." },
      { term: "Proximal", def: "Closer to the body core." },
      { term: "Distal", def: "Farther from the body core." },
      { term: "Dermatome", def: "The area of skin innervated by a single pair of spinal nerves." },
      { term: "Cervical nerves", def: "The 8 pairs of spinal nerves in the neck region." },
      { term: "Thoracic nerves", def: "The 12 pairs of spinal nerves in the torso/rib cage region." },
      { term: "Lumbar nerves", def: "The 5 pairs of spinal nerves in the lower back region." },
      { term: "Sacral nerves", def: "The 5 pairs of spinal nerves in the pelvic region." },
      { term: "Coccygeal nerve", def: "The single pair of spinal nerves at the very bottom of the spinal cord." },
      { term: "Gray matter", def: "Nervous system tissue containing cell bodies (no myelin) — appears gray." },
      { term: "White matter", def: "Nervous system tissue containing myelinated axons — appears white due to the fatty myelin." },
      { term: "Oligodendrocyte", def: "The glial cell that produces myelin in the central nervous system." },
      { term: "Dorsal horn", def: "The part of the spinal cord's gray matter that receives incoming sensory (afferent) information." },
      { term: "Ventral horn", def: "The part of the spinal cord's gray matter containing motor neuron cell bodies that send efferent output." },
      { term: "Dorsal root", def: "The sensory nerve fiber entering the dorsal side of the spinal cord." },
      { term: "Ventral root", def: "The motor nerve fiber exiting the ventral side of the spinal cord." },
      { term: "Intervertebral foramen", def: "The space between vertebrae where spinal nerves enter and exit." },
      { term: "Dorsal root ganglion", def: "A collection of sensory neuron cell bodies located just outside the spinal cord." },
      { term: "Ganglion", def: "A collection of cell bodies located outside the central nervous system." },
      { term: "Neuromuscular junction", def: "The synapse between a motor neuron and a muscle fiber." },
      { term: "Acetylcholine", def: "The neurotransmitter released at the neuromuscular junction that causes muscle contraction." }
    ]
  },

  "lecture10-psyc2200": {
    title: "Lecture 10",
    subtitle: "Reflexes, brainstem, cranial nerves, midbrain, diencephalon, telencephalon & cerebral cortex",
    terms: [
      { term: "Monosynaptic reflex", def: "A reflex circuit involving only one synapse (e.g., pulling your hand off a hot object before you consciously feel pain)." },
      { term: "Disynaptic reflex", def: "A reflex circuit involving two synapses, still not requiring the brain to process it." },
      { term: "Crossed-extensor reflex", def: "A reflex where one limb withdraws (flexes) from a painful stimulus while the opposite limb extends to bear weight and keep balance." },
      { term: "Pyramidal decussation", def: "The point in the medulla where axon tracts cross from one side of the body to the other; the boundary between spinal cord and brain." },
      { term: "Decussation", def: "The anatomical term meaning 'crossing over' from one side to the other." },
      { term: "Contralateral", def: "Referring to the opposite side of the body." },
      { term: "Ipsilateral", def: "Referring to the same side of the body." },
      { term: "Medulla oblongata", def: "The most caudal part of the brainstem; controls survival functions like breathing and heartbeat. Developmentally, the myelencephalon." },
      { term: "Sagittal section", def: "A cut through the midline of the brain that separates the left and right sides." },
      { term: "Coronal section", def: "A crown-like cut that separates the front and back portions of the brain." },
      { term: "Horizontal section", def: "A cut that separates the brain into top and bottom slices." },
      { term: "Pons", def: "A brainstem structure sitting above the medulla, part of the metencephalon." },
      { term: "Cerebellum", def: "A hindbrain (metencephalon) structure responsible for fine, discrete motor coordination and movement feedback; contains a majority of the brain's neurons." },
      { term: "Central canal", def: "The fluid-filled channel running through the center of the spinal cord's gray matter; a developmental remnant of the neural tube." },
      { term: "Ventricles", def: "Fluid-filled cavities in the brain, continuous with the spinal cord's central canal, filled with cerebrospinal fluid." },
      { term: "Lateral ventricles", def: "The two large ventricles located in the forebrain (telencephalon)." },
      { term: "Choroid plexus", def: "The tissue that continuously produces cerebrospinal fluid." },
      { term: "Cerebrospinal fluid (CSF)", def: "Fluid that cushions and protects the brain, removes toxins, and bathes the brain and spinal cord." },
      { term: "Meninges", def: "The three membranes that encase the brain and spinal cord, containing the cerebrospinal fluid." },
      { term: "Meningitis", def: "Inflammation of the meninges, which puts pressure on the brain and causes headaches; can be dangerous." },
      { term: "Cranial nerves", def: "The 12 pairs of nerves that bring sensory information in and send motor information out for the head; unlike spinal nerves, they can be purely sensory, purely motor, or mixed." },
      { term: "Olfactory nerve (CN I)", def: "The cranial nerve responsible for smell." },
      { term: "Optic nerve (CN II)", def: "The cranial nerve responsible for vision." },
      { term: "Trigeminal nerve (CN V)", def: "The cranial nerve responsible for facial touch and temperature sensation." },
      { term: "Facial nerve (CN VII)", def: "The cranial nerve responsible for facial muscle movement and expression." },
      { term: "Vagus nerve (CN X)", def: "The cranial nerve that innervates the gut and carries some taste information." },
      { term: "Tegmentum", def: "The bottom portion of the midbrain; contains the reticular formation." },
      { term: "Reticular formation", def: "A midbrain structure responsible for wakefulness, attention, and arousal — like a 'volume knob' for consciousness." },
      { term: "Tectum", def: "The roof of the midbrain, containing the superior and inferior colliculi." },
      { term: "Superior colliculus", def: "A midbrain structure responsible for visual processing and orienting to stimuli." },
      { term: "Inferior colliculus", def: "A midbrain structure responsible for auditory processing and orienting to stimuli." },
      { term: "Hypothalamus", def: "A diencephalon structure that regulates homeostasis (water/weight balance) and controls the pituitary gland/endocrine system." },
      { term: "Pituitary gland", def: "The 'master gland' attached to the hypothalamus that controls the endocrine system." },
      { term: "Thalamus", def: "A diencephalon structure that serves as the major sensory relay between lower brain areas and the cerebral cortex." },
      { term: "Lateral geniculate nucleus (LGN)", def: "The thalamic nucleus that relays visual information from the eye to the visual cortex." },
      { term: "Specific sensory nuclei", def: "Thalamic nuclei that relay a single sensory modality to a specific cortical area." },
      { term: "Specific motor nuclei", def: "Thalamic nuclei that relay information related to movement to motor cortex." },
      { term: "Specific association nuclei", def: "Thalamic nuclei thought to integrate sensory and motor information for a given region." },
      { term: "Nonspecific nuclei", def: "Thalamic nuclei with diffuse connections spread across the whole cerebral cortex." },
      { term: "Pineal gland", def: "The topmost diencephalon structure, involved in regulating circadian rhythms." },
      { term: "Olfactory bulb", def: "A deep telencephalic structure responsible for processing smell; most developed in mammals." },
      { term: "Basal ganglia", def: "A collection of telencephalic nuclei (caudate, putamen, globus pallidus) involved in organizing and monitoring motor movement." },
      { term: "Globus pallidus", def: "A basal ganglia structure involved in motor movement." },
      { term: "Hippocampus", def: "A deep telencephalic structure in the temporal lobe responsible for learning and memory, especially short-term." },
      { term: "Amygdala", def: "A deep telencephalic structure involved in processing emotions and fast processing of some sensory information." },
      { term: "Corpus callosum", def: "The large white-matter tract connecting the left and right cerebral hemispheres; severed in split-brain surgery." },
      { term: "Sulcus", def: "A valley or groove in the cerebral cortex." },
      { term: "Gyrus", def: "A ridge in the cerebral cortex." },
      { term: "Frontal lobe", def: "The cortical lobe containing the motor cortex and responsible for higher-order processing — judgment, reasoning, personality." },
      { term: "Parietal lobe", def: "The cortical lobe containing the somatosensory cortex — processes touch and pain from the body." },
      { term: "Temporal lobe", def: "The cortical lobe responsible for language processing and hearing." },
      { term: "Occipital lobe", def: "The cortical lobe responsible for vision." },
      { term: "Limbic lobe", def: "The cingulate gyrus; a cortical region involved in emotion." },
      { term: "Central sulcus", def: "The groove that divides the frontal lobe from the parietal lobe." },
      { term: "Precentral gyrus", def: "The primary motor cortex, located in the frontal lobe just in front of the central sulcus." },
      { term: "Postcentral gyrus", def: "The primary somatosensory cortex, located in the parietal lobe just behind the central sulcus." },
      { term: "Brodmann areas", def: "Numbered regions of the cerebral cortex, defined by cytoarchitectonics (cell structure across the 6 cortical layers)." },
      { term: "Area 17", def: "The primary visual cortex, in Brodmann's numbering system." },
      { term: "Area 41", def: "The primary auditory cortex, in Brodmann's numbering system." },
      { term: "Area 4", def: "The primary motor cortex, in Brodmann's numbering system." }
    ]
  },

  "lecture11-psyc2200": {
    title: "Lecture 11",
    subtitle: "Neural development: chemoaffinity, synaptogenesis, apoptosis & plasticity",
    terms: [
      { term: "Central Nervous System (CNS) Development", def: "The process by which the brain and spinal cord grow from a few embryonic cells into the mature, complex structure seen in adulthood; it is a continuous process that extends well past birth, not something complete at birth." },
      { term: "T1-Weighted MRI Image", def: "A type of magnetic resonance image in which myelinated (white matter) tissue appears bright/white, used to track how much myelination has occurred in a developing brain." },
      { term: "T2-Weighted MRI Image", def: "A type of magnetic resonance image that, together with T1 images, is used to visualize the relative amounts of gray matter (cell bodies) versus white matter (myelinated axons) in the brain." },
      { term: "Gray Matter", def: "Brain tissue composed mainly of neuron cell bodies; it increases sharply around birth and then its thickness/surface area tends to plateau or decline later in development." },
      { term: "White Matter", def: "Brain tissue composed mainly of myelinated axons; unlike gray matter, it continues to increase steadily even into early adulthood (around 20 years of age)." },
      { term: "Neural Tube", def: "The early embryonic structure that folds up from a thickened strip of tissue and gives rise to the entire central nervous system; its fluid-filled interior becomes the central canal and ventricles." },
      { term: "Five Brain Vesicles (Myelencephalon, Metencephalon, Mesencephalon, Diencephalon, Telencephalon)", def: "The five pouches that the front end of the neural tube divides into early in development, which go on to form the major regions of the adult brain." },
      { term: "Radial Glia", def: "Specialized glial cells that span the neural tube from inside to outside, acting like scaffolding tracks that guide migrating immature neurons to their correct final locations." },
      { term: "Brain Stem Matures First", def: "A general principle of neural development stating that caudal (lower, posterior) brain structures like the brainstem develop and form synapses before higher structures like the cerebral cortex, reflecting their importance for basic survival functions such as breathing and heart rate." },
      { term: "Motor-Before-Sensory Development", def: "A developmental principle stating that motor (muscle-control) systems come online before sensory systems, likely because the ability to move (e.g., to escape danger) is more immediately critical for survival." },
      { term: "Projection Neuron", def: "A relatively large neuron that sends its axon long distances between different brain structures, analogous to a 'highway' connecting distant regions; these neurons typically develop before interneurons." },
      { term: "Interneuron (Microneuron)", def: "A small neuron that makes local connections within a single structure rather than projecting elsewhere in the brain; these develop after projection neurons, refining local circuitry once long-range communication is established." },
      { term: "Neural Proliferation", def: "The process of producing new neurons through cell division; given that the brain contains roughly 10^11 (100 billion) neurons that must be produced within about nine months of gestation, an enormous number of new neurons must be generated every minute." },
      { term: "Neuronal Migration", def: "The process by which newly formed neurons move away from the area near the fluid-filled neural tube (where they were born) to their permanent final locations in the nervous system, sometimes traveling in complex, crossing, or indirect paths." },
      { term: "Cortical Histogenesis", def: "The developmental process by which the six layers of the cerebral cortex are formed in a precise order, illustrating how newly born cortical neurons know where to settle within the layered structure." },
      { term: "Inside-Out Pattern of Cortical Layering", def: "The principle that the oldest cortical neurons settle in the deepest (lowest, near the ventricles) layers first, while progressively younger neurons migrate past them to settle in more superficial layers, building the six-layered cortex from the inside out." },
      { term: "Subventricular Zone (SVZ)", def: "A region located near the ventricles where many new cortical neurons are generated before migrating outward to their final cortical layer." },
      { term: "Cortical Column (Functional Unit)", def: "A vertically organized group of interconnected neurons spanning the six cortical layers that acts as a basic functional processing unit; because migrating neurons 'communicate' with earlier-arriving cells as they pass through, each column becomes a coordinated circuit." },
      { term: "Gyri and Sulci Formation", def: "The folding of the cerebral cortex into ridges (gyri) and grooves (sulci), which increases surface area so that more cortical columns (functional units) can fit without needing a thicker cortex, allowing for greater computational complexity in larger brains." },
      { term: "Neuronal Differentiation", def: "The process by which a migrated neuron takes on its specific mature form and identity, including growing axons and dendrites and forming the appropriate synaptic connections." },
      { term: "Growth Cone", def: "The actively exploring tip at the end of a growing axon (or dendrite) that senses the environment and guides the extending process toward its proper target." },
      { term: "Axogenesis", def: "The growth and formation of a neuron's axon, which occurs before dendrite formation as the neuron's growth cone seeks out and contacts target cells." },
      { term: "Dendrogenesis", def: "The growth and formation of a neuron's dendrites, which occurs after axon formation (axogenesis), typically once the axon has already made initial contact with a target cell." },
      { term: "Synaptogenesis", def: "The formation of synaptic connections between neurons, occurring after axons and dendrites have grown; because there are far too few genes to specify every one of the roughly 10^15 synapses individually, experience-driven mechanisms must help shape synapse formation." },
      { term: "Point-to-Point Visual Map", def: "The precise topographic correspondence between a location on the retina and a corresponding location in visual brain areas (such as the tectum/superior colliculus), so that neighboring points in the visual world remain neighbors throughout the visual processing pathway." },
      { term: "Tectum / Superior Colliculus", def: "A midbrain structure (part of the mesencephalon) that integrates visual information and contains a precise topographic map of the retina; it is the main visual processing center in frogs, birds, reptiles, and amphibians, and is homologous to the superior colliculus in mammals." },
      { term: "Roger Sperry", def: "A neuroscientist who studied how developing retinal axons find their correct targets in the brain by surgically rotating frog eyes and observing where regenerated optic nerve fibers reconnected; his work led to the chemoaffinity hypothesis." },
      { term: "Sperry's Eye Rotation Experiment", def: "An experiment in which Roger Sperry severed and rotated the eye of an African clawed frog 180 degrees; after regeneration, the optic nerve fibers reconnected to their original targets in the tectum rather than the targets appropriate for the new (rotated) orientation, causing the frog to respond to stimuli as if they were 180 degrees reversed. This showed that axon targeting is guided by intrinsic chemical cues rather than visual experience." },
      { term: "Chemoaffinity Hypothesis", def: "Roger Sperry's proposed explanation for how axons find their targets, stating that growing axons are guided by gradients of specific chemical cues ('molecular zip codes') secreted in the target tissue, and that axons grow toward the region matching the receptors they carry." },
      { term: "Ephrins", def: "A family of signaling molecules identified as part of the chemical gradient system in the tectum that helps guide retinal axons to their correct topographic locations, consistent with the chemoaffinity hypothesis." },
      { term: "Nature vs. Nurture (in Axon Guidance)", def: "The debate over whether axons find their targets through genetically programmed, intrinsic chemical cues (nature) or through activity-based experience and cues picked up along the way (nurture); Sperry's work supported a strong role for intrinsic (genetically guided) chemical cues, though timing/spatial cues (a form of 'nurture') also matter in many contexts." },
      { term: "Birth Order as a Developmental Cue", def: "The principle that a neuron's eventual cortical layer or position can be determined simply by when and where it is born relative to other cells, since earlier-born cells occupy available space first and later-born cells must settle further along, independent of any specific molecular target-seeking cue." },
      { term: "Apoptosis", def: "Programmed cell death, a normal and genetically regulated process (distinct from injury-related cell death) by which the nervous system eliminates neurons that fail to make functional, useful connections; roughly twice as many neurons exist at certain embryonic stages as survive into adulthood." },
      { term: "Trochlear Nerve Overproduction Example", def: "A classic illustration of apoptosis: the trochlear nucleus (fourth cranial nerve) starts with roughly 1,200 neurons at embryonic day 11, but about half die off during development, leaving only the neurons that successfully formed functional connections." },
      { term: "Target-Size (Trophic) Effect", def: "The principle that the size of a neuron's target tissue influences how many of its originally overproduced neurons survive apoptosis, because a larger target offers more available sites for forming functional synaptic connections." },
      { term: "Frog Limb Transplant Experiment", def: "An experiment in which extra limbs were transplanted onto one side of a frog or toad embryo; the increased target tissue allowed an increased number of spinal motor neurons on that side to survive and make functional connections, demonstrating the target-size/trophic effect on neuron survival." },
      { term: "Neuronal Overproduction", def: "The phenomenon whereby roughly twice as many neurons (and roughly twice as many dendrites, axons, and synapses) are produced during development as will ultimately survive in the adult nervous system, with the excess later eliminated through apoptosis and pruning." },
      { term: "Synaptic Pruning", def: "The elimination of excess synapses, dendrites, and axonal branches during development, streamlining neural circuits so that only functionally useful connections are retained in the mature nervous system." },
      { term: "Glial Proliferation Timing", def: "The developmental principle that glial cells are generally produced after neurons; glial proliferation occurs around the neural tube like neuronal proliferation, but on a separate, later schedule, with some glial types (like microglia) originating from entirely different tissue sources." },
      { term: "Microglia", def: "A type of glial cell that originates from a different developmental source (outside the neural tube, related to the immune system) compared to other glial cells like astrocytes." },
      { term: "Astrocyte", def: "A type of glial cell that, like neurons, can migrate away from the neural tube to its final location during development, supporting neurons metabolically and structurally." },
      { term: "William (Bill) Greenough", def: "A researcher known for experiments raising rats in enriched versus impoverished environments and using Golgi staining to show that environmental richness dramatically affects dendrite number, synapse number, and overall neuronal complexity." },
      { term: "Enriched Environment", def: "A housing condition for laboratory animals (e.g., rats) that includes social companions and objects to climb on and interact with, associated with increased dendritic branching and synapse number compared to impoverished housing." },
      { term: "Impoverished Environment", def: "A housing condition for laboratory animals in which an animal is isolated with only basic necessities (food and water) and no social or physical enrichment, associated with reduced dendritic branching and fewer synapses compared to enriched housing." },
      { term: "Golgi Stain (Applied to Greenough's Work)", def: "A staining technique used by Greenough to visualize whole neurons (cell body, dendrites, axons, and spines) in order to compare neuronal complexity between rats raised in enriched versus impoverished environments." },
      { term: "Control Group Problem in Enrichment Studies", def: "The methodological issue that a standard laboratory housing condition may actually represent an impoverished environment relative to an animal's natural habitat, raising the question of whether the 'enriched' condition is really the appropriate control rather than the deprived one." },
      { term: "Nursing Home vs. Active Lifestyle Brain Study", def: "A human study comparing the brains of elderly individuals who died in nursing homes (generally less environmentally stimulating) to those of similarly aged individuals who died while still leading active lifestyles (e.g., in an accident like skydiving); nursing home residents were found to have smaller brains, supporting a lifelong effect of environmental enrichment on brain structure." },
      { term: "Kelly Lambert", def: "A researcher and textbook author referenced in the course who has studied the effects of impoverished environments, maternal behavior, and stress on brain plasticity and development." },
      { term: "Brain Plasticity (Neurodevelopmental Context)", def: "The capacity of the nervous system to change its structure and connectivity in response to experience, demonstrated across species and across the lifespan by enrichment/impoverishment studies and other environmental experiments." },
      { term: "Functional Experience and Synapse Maintenance", def: "The principle that whether a given synapse or neuron survives development depends on whether it is actively used in functional neural activity; connections that are not used tend to be eliminated through pruning or apoptosis." }
    ]
  },

  "lecture13-psyc2200": {
    title: "Lecture 13",
    subtitle: "Vision: LGN, visual cortex, feature detection & critical-period plasticity",
    terms: [
      { term: "Lateral Geniculate Nucleus (LGN)", def: "A relay structure in the thalamus that receives input from retinal ganglion cells and passes visual information on to the visual cortex via the optic radiation; it preserves a point-to-point retinotopic map of the retina." },
      { term: "Optic Radiation", def: "The bundle of axons that carries visual information from the lateral geniculate nucleus of the thalamus back to the primary visual cortex." },
      { term: "Retinotopic Map", def: "An organized representation of visual space in which neighboring points on the retina project to neighboring neurons in a visual structure (such as the LGN or cortex), preserving spatial relationships." },
      { term: "Cortical Magnification", def: "The phenomenon in which brain regions representing high-density, highly sensitive parts of a sensory surface (like the fovea) are allocated disproportionately more neural tissue than less sensitive regions." },
      { term: "Fovea", def: "The central region of the retina packed almost exclusively with cones, giving it the highest visual acuity; it occupies a disproportionately large area of the retinotopic map in the LGN and cortex." },
      { term: "Parvocellular Cells (X Cells)", def: "Small ganglion cells concentrated near the center of the retina that are specialized for detecting fine spatial detail; they synapse onto the parvocellular layers of the LGN." },
      { term: "Magnocellular Cells (Y Cells)", def: "Larger ganglion cells concentrated in the peripheral retina that are specialized for detecting movement; they synapse onto the magnocellular layers of the LGN." },
      { term: "Layered Structure of the LGN", def: "The LGN is organized into about six distinct layers, segregated both by cell type (parvocellular vs. magnocellular) and by which eye (contralateral vs. ipsilateral) provides the input." },
      { term: "Contralateral Eye Input", def: "Visual input to the LGN coming from the opposite-side eye; in the LGN this input terminates in specific layers that are kept separate from ipsilateral input." },
      { term: "Ipsilateral Eye Input", def: "Visual input to the LGN coming from the same-side eye; it terminates in LGN layers distinct from those receiving contralateral input, maintaining eye-of-origin segregation." },
      { term: "Primary Visual Cortex (V1 / Brodmann Areas 17 and 18)", def: "The first cortical area to receive visual information from the LGN, located in the occipital lobe; it contains a precise spatial map of the visual world and is the starting point for cortical feature extraction." },
      { term: "David Hubel and Torsten Wiesel", def: "Nobel Prize-winning neuroscientists who in the late 1950s-1960s discovered how neurons in the visual cortex respond to specific features like oriented edges and motion, revealing that the visual system is a feature detector rather than a simple light detector." },
      { term: "Serendipity in the Hubel and Wiesel Experiments", def: "Hubel and Wiesel initially could not activate visual cortex neurons with spots of light; they stumbled upon the correct stimulus (a moving edge/line) accidentally when a glass slide's shadow swept across the cat's retina while they were changing lenses." },
      { term: "Ophthalmoscope", def: "An instrument used to shine and observe a focused point of light on the back of the eye, originally used by Hubel and Wiesel in their attempts to stimulate the visual cortex." },
      { term: "Animal Care and Use Committee (IACUC)", def: "An institutional oversight body, including veterinarians and community members, that reviews and approves research protocols involving animals to ensure the research is justified, ethical, and minimizes animal pain or distress." },
      { term: "Simple Cell", def: "A neuron in the primary visual cortex that fires maximally in response to a line or edge of a specific orientation located in a specific position in the visual field." },
      { term: "Complex Cell", def: "A neuron in the visual cortex that, like a simple cell, requires a specific orientation and location, but additionally requires the stimulus to be moving in a particular direction in order to fire." },
      { term: "Orientation Selectivity", def: "The property of visual cortex neurons (simple and complex cells) that makes them respond preferentially to lines or edges at a specific angle rather than to light in general." },
      { term: "Feature Detection (Visual Cortex)", def: "The principle, established by Hubel and Wiesel, that visual cortex neurons are tuned to extract specific stimulus features (such as orientation, edges, and motion) rather than simply responding to the presence of light." },
      { term: "Convergent Wiring of Simple Cells", def: "A simple cell receives input from a specific subset of ganglion cells (relayed through the LGN) arranged in a line; only when light activates that whole line of inputs does spatial summation produce enough depolarization to trigger an action potential." },
      { term: "Spatial Summation (Visual Cortex Context)", def: "The process by which multiple simultaneous subthreshold inputs (e.g., from several ganglion/LGN cells aligned along a bar of light) add together at a simple or complex cell to reach the threshold needed for an action potential." },
      { term: "Temporal Summation (Visual Cortex Context)", def: "The process by which inputs arriving at a cell in rapid succession add together over time; used to explain how timing differences in axon conduction let a complex cell detect motion direction." },
      { term: "Direction-Selective Wiring (Complex Cells)", def: "A wiring scheme in which inputs from simple cells responding to sequential positions reach a complex cell with carefully timed delays (via differences in axon length, diameter, or myelination) so that a line moving in one direction causes all inputs to arrive simultaneously and sum, while movement in the opposite direction causes them to arrive out of phase and fail to sum." },
      { term: "Axon Conduction Delay Mechanisms", def: "Ways the nervous system can control how quickly a signal travels down an axon, including varying axon length, axon diameter (caliber), and degree of myelination, used to precisely time inputs converging on downstream neurons like complex cells." },
      { term: "Hierarchical Model of Visual Processing", def: "The concept that visual information passes through successive processing stages (photoreceptors to bipolar cells to ganglion cells to LGN relay cells to simple cells to complex cells and beyond), with each stage extracting progressively more complex features from a progressively smaller number of more specialized cells." },
      { term: "Feature Extraction", def: "The general process by which the visual system (and other sensory systems) progressively distills raw sensory input into meaningful, abstracted information such as edges, motion, shapes, and eventually objects or faces." },
      { term: "Hand-Selective Neurons (Monkey Visual Cortex)", def: "An anecdote describing neurons in monkey visual cortex that fired specifically to the sight of a moving hand shape, illustrating that higher visual areas can be tuned to complex, ecologically relevant stimuli rather than simple lines or spots." },
      { term: "Fusiform Gyrus", def: "A region located in the inferior temporal lobe that is specialized for facial recognition, allowing rapid identification of faces and individual identities from visual input." },
      { term: "Face Pareidolia", def: "The tendency of the facial recognition system (including the fusiform gyrus) to perceive faces in ambiguous or inverted images, even when no face is actually present, as illustrated by the famous 'face on a food item' anecdotes." },
      { term: "Face Inversion Effect", def: "The phenomenon in which flipping a face image upside down dramatically impairs the ability to recognize it normally, demonstrating that facial recognition relies on specialized, orientation-sensitive processing rather than generic shape perception." },
      { term: "Magnocellular Pathway (Cortical)", def: "One of the major visual processing streams leaving the primary visual cortex, specialized for extracting motion information and feeding into brain areas involved in planning motor responses to moving stimuli." },
      { term: "Parvocellular Pathway (Cortical)", def: "One of the major visual processing streams leaving the primary visual cortex, specialized for extracting fine spatial detail and complex shape information, projecting toward the temporal lobe." },
      { term: "Mixed (Blob) Pathway", def: "A third visual processing stream, carrying combined information including color and brightness, that projects into the temporal lobe alongside the magnocellular and parvocellular pathways." },
      { term: "Ventral and Dorsal Visual Streams", def: "The broader organization in which visual information extracted in the occipital cortex is distributed further into the parietal cortex (motion/spatial processing, dorsal stream) and temporal cortex (object/shape/color processing, ventral stream)." },
      { term: "Visual System as a Developmental Model", def: "The idea that researchers favor the visual system for studying brain development because its highly ordered, point-to-point retinotopic maps and well-defined pathways make it relatively easy to trace how neural wiring forms and depends on experience." },
      { term: "Activity-Dependent Synaptic Strengthening", def: "The principle that when converging inputs are activated together at a target neuron, those synapses are reinforced (consistent with Hebbian-type plasticity), whereas lack of coordinated activity results in weaker or absent connections." },
      { term: "Astigmatism", def: "A vision condition caused by an irregularly shaped (non-spherical) cornea, which causes light to be imperfectly focused on the retina and can make certain line orientations appear blurrier than others." },
      { term: "Astigmatism Line-Orientation Test", def: "A clinical test in which a patient views sets of parallel lines at different orientations from a distance and reports when two lines become distinguishable as they move closer, used to detect which orientations are blurred by astigmatism." },
      { term: "Goggle-Rearing Kitten Experiment", def: "A classic developmental study in which kittens were raised wearing goggles that allowed one eye to see only vertical lines and the other eye to see only horizontal lines; as adults, cortical neurons had developed to respond almost exclusively to the orientation each eye had experienced, demonstrating that early visual experience shapes cortical wiring." },
      { term: "Critical Period of Visual Development", def: "A limited early developmental window during which visual experience is required to properly wire orientation-selective neurons in the visual cortex; after this window closes, missing experience (e.g., exposure to certain line orientations) cannot be fully compensated for later." },
      { term: "Uncorrected Astigmatism and Adult Deficits", def: "Human studies showed that adults with severe untreated astigmatism since early life, even after their vision was later perfectly corrected with lenses, still could not perceive certain line orientations normally, demonstrating a lasting developmental deficit in cortical processing despite a normally functioning retina." },
      { term: "Experience-Dependent Plasticity", def: "The broader principle, illustrated by both the kitten and human astigmatism studies, that early sensory experience is necessary to properly establish the neural circuits that extract and represent specific stimulus features." },
      { term: "Connectomics", def: "A research approach that aims to map the complete wiring diagram (all neurons and their synaptic connections) of a piece of neural tissue, used to gain detailed insight into how circuits like motion detection are physically organized." },
      { term: "Electron Microscopy Reconstruction of Neural Tissue", def: "A technique in which thin tissue slices are imaged with an electron microscope and then digitally reconstructed, with computer algorithms and large-scale human tracing used to rebuild the three-dimensional shapes and connections of individual neurons." },
      { term: "T4 and T5 Neurons (Fly Visual System)", def: "Downstream motion-processing neurons in the fruit fly visual system, found to be divided into four subpopulations, each tuned to detect motion in one of the four cardinal directions (up, down, left, right)." },
      { term: "Motion Detection Circuit (Fly Visual System)", def: "A neural circuit, mapped through connectomics and confirmed with activity imaging, that explains how the fly brain computes the direction of visual motion using precisely wired connections among retinal and downstream neurons." },
      { term: "Center-Surround Organization (Review Context)", def: "An organizational principle, carried over from the retina into the LGN, in which a stimulus directly over a cell's receptive field produces one response (e.g., excitation) while the same stimulus just outside that field produces the opposite response (e.g., inhibition)." },
      { term: "Optic Chiasm (Review Context)", def: "The point where axons from each retina partially cross, so that information from the left visual field is routed to the right side of the brain and vice versa, a principle carried through to the LGN's layered organization." },
      { term: "Cat LGN Model", def: "A commonly used experimental model showing a clear six-layered, retinotopically organized lateral geniculate nucleus, used by researchers to study how visual connections are precisely wired during development." },
      { term: "Topographic Mapping Principle", def: "The lawful developmental pattern in which retinal ganglion cell axons grow to connect with precisely corresponding locations in their target structures (like the LGN), preserving spatial order from retina to brain." }
    ]
  },

  "lecture14-psyc2200": {
    title: "Lecture 14",
    subtitle: "Audition: sound, the ear, the cochlea & pitch coding",
    terms: [
      { term: "Frequency", def: "The number of sound pressure oscillations that pass a given point per unit of time, measured in Hertz; this is what we perceive as the pitch of a sound (low tone versus high tone)." },
      { term: "Hertz (Hz)", def: "The unit used to measure frequency, equal to one oscillation (cycle) per second; for example, 100 Hz means 100 pressure wave cycles occur every second." },
      { term: "Kilohertz (kHz)", def: "A unit equal to 1,000 Hertz, used because audible sound frequencies span a wide range, from about 20 Hz up to roughly 20 kHz in humans with optimal hearing." },
      { term: "Amplitude", def: "How tall or short a sound wave is, which corresponds to how loud or quiet a sound seems to a listener; amplitude is measured using decibels." },
      { term: "Decibel (dB)", def: "The unit used to measure the loudness (amplitude) of a sound, on a scale starting at 0 dB (the absolute threshold of hearing)." },
      { term: "Pitch", def: "The perceptual quality of a sound corresponding to its frequency; higher frequency waveforms are heard as higher-pitched tones and lower frequency waveforms as lower-pitched tones." },
      { term: "Loudness", def: "The perceptual quality of a sound corresponding to its amplitude (wave height); it is measured objectively in decibels." },
      { term: "Timbre", def: "The characteristic quality or 'flavor' of a note produced by the combination of harmonics layered on top of its fundamental frequency, which is why the same note (e.g., concert A) sounds different when played on a piano versus a cello." },
      { term: "Harmonics", def: "The additional overtones that accompany a fundamental frequency when a real instrument produces a note; different combinations of harmonics give each instrument its unique timbre." },
      { term: "Logarithmic Scale of Decibels", def: "The decibel scale is not simply additive; for example, doubling the number of identical sound sources in a room does not double the decibel level, but instead causes only a modest increase (e.g., from 60 dB to about 64 dB)." },
      { term: "Absolute Threshold of Hearing (0 dB)", def: "The quietest sound intensity humans can detect, defined as 0 decibels; in a fully soundproof chamber, people become sensitive enough after a period of time to hear internal body sounds like their own heartbeat or blood flow." },
      { term: "Pain Threshold (120 dB)", def: "The sound intensity level, around 120 decibels, at which sound becomes physically painful to the ears, comparable to standing directly behind a jet engine." },
      { term: "Noise-Induced Hearing Loss", def: "Hearing damage caused by repeated exposure to sounds above roughly 90 decibels, such as standing near concert speakers or using headphones/earbuds at excessive volume; this damage accumulates and leads to premature hearing loss." },
      { term: "Age-Related High-Frequency Hearing Loss (Presbycusis)", def: "The gradual, permanent loss of the ability to hear high- and low-frequency sounds that occurs naturally with aging; high frequencies are typically lost first, which is why older adults (especially men) often struggle to hear higher-pitched voices like those of women and children." },
      { term: "Audible Range (20 Hz-20,000 Hz)", def: "The normal human range of hearing under ideal conditions, from about 20 Hz at the low end to about 20,000 Hz (20 kHz) at the high end; this range narrows with age, and once frequencies at either extreme are lost, they typically cannot be recovered." },
      { term: "Pinna (Auricle)", def: "The visible, cartilage-shaped external ear structure that sits on either side of the head; its name comes from the Latin word for 'wings,' and it functions to catch and funnel sound waves and assist with sound localization." },
      { term: "External Auditory Meatus (Ear Canal)", def: "The canal running from the pinna into the skull that channels incoming sound waves toward the eardrum." },
      { term: "Tympanic Membrane (Eardrum)", def: "A thin membrane at the end of the ear canal that vibrates in response to incoming sound pressure at the specific frequency of the sound; despite being easily damaged because it is so thin, it has a remarkable ability to regenerate almost perfectly." },
      { term: "Middle Ear", def: "The air-filled cavity located between the eardrum and the inner ear that houses the chain of tiny bones (ossicles) responsible for conducting and amplifying sound vibrations toward the cochlea." },
      { term: "Ossicles", def: "The three smallest bones in the human body, connected in a chain within the middle ear, that transmit vibrations from the eardrum to the oval window while amplifying the signal along the way." },
      { term: "Middle Ear Amplification Mechanism", def: "The ossicles boost the sound signal through two combined effects: concentrating vibrational energy from the large eardrum onto the much smaller oval window (like a hammer striking a nail), and using a lever-like mechanical action between the three bones, together amplifying the signal roughly 200-fold." },
      { term: "Eustachian Tube", def: "A tube connecting the middle ear to the back of the throat that equalizes air pressure between the outer and inner sides of the eardrum (e.g., during altitude changes); it is not directly involved in hearing but can become painfully inflamed if it malfunctions." },
      { term: "Oval Window", def: "A small membrane-covered opening at the base of the cochlea where the ossicles deliver amplified vibrations, marking the entry point of sound energy into the fluid-filled inner ear." },
      { term: "Cochlea", def: "A small, snail-shell-shaped, fluid-filled structure in the inner ear (about 10 mm wide with roughly two and a quarter turns) that transduces mechanical sound vibrations into neural signals." },
      { term: "Scala Vestibuli", def: "The uppermost of the three fluid-filled canals that run the length of the unrolled cochlea, beginning at the oval window." },
      { term: "Scala Tympani", def: "The lowermost of the three fluid-filled canals in the cochlea, connected to the scala vestibuli around the cochlea's tip and ending near the round window." },
      { term: "Scala Media (Cochlear Duct)", def: "The middle of the three cochlear canals, sandwiched between the scala vestibuli and scala tympani, which houses the basilar membrane, tectorial membrane, and the organ of Corti." },
      { term: "Basilar Membrane", def: "A membrane forming the floor of the scala media that vibrates in response to fluid movement in the cochlea; it is attached at one end to the oval window area but free at the other, allowing it to flex and vibrate at specific frequencies." },
      { term: "Tectorial Membrane", def: "A gelatinous membrane that lies above the hair cells in the organ of Corti, attached on only one side; because it vibrates slightly out of sync with the basilar membrane beneath it, the resulting relative motion bends the hair cells' cilia." },
      { term: "Organ of Corti", def: "The sensory structure within the scala media that contains the basilar membrane, the hair cells, and the tectorial membrane together; this is where mechanical sound vibrations are converted into neural signals." },
      { term: "Hair Cells", def: "The sensory receptor cells of the auditory system, embedded in the organ of Corti, that have hair-like cilia projecting from their apical surface; when these cilia are bent by motion between the basilar and tectorial membranes, the cells generate a neural signal." },
      { term: "Cilia (Stereocilia)", def: "Hair-like projections on the apical surface of hair cells, arranged in rows of increasing height and linked together by tip links; their bending in response to membrane motion triggers the opening or closing of ion channels." },
      { term: "Tip Links", def: "Tiny filament-like connections joining the tips of adjacent stereocilia on a hair cell; they act like interconnected strings so that displacing one cilium pulls on its neighbors, somewhat like a row of dominoes." },
      { term: "Hair Cell Mechanotransduction", def: "The process by which bending of the cilia (via tip links) physically opens or closes ion channels at the tips; bending in one direction opens channels and lets sodium in while potassium exits (depolarizing the cell), while bending the opposite way closes channels and hyperpolarizes the cell." },
      { term: "Depolarization (Hair Cell)", def: "When hair cell cilia are displaced in the activating direction, ion channels open, sodium flows in and potassium flows out, making the cell more likely to fire and signal the brain." },
      { term: "Hyperpolarization (Hair Cell)", def: "When hair cell cilia are displaced in the opposite, non-preferred direction, the cell becomes hyperpolarized and is less likely to fire, effectively reducing its signal to the brain." },
      { term: "Auditory Nerve (Cranial Nerve VIII)", def: "The eighth cranial nerve, which carries action potentials from the base of the hair cells in the organ of Corti out of the cochlea and up to the brain for auditory processing." },
      { term: "Frequency Theory", def: "An early theory of pitch coding proposing that a hair cell fires at exactly the same frequency as the incoming sound wave; this breaks down above roughly 200 Hz because neurons cannot fire fast enough due to their refractory period, making it unable to explain our full hearing range." },
      { term: "Volley Theory", def: "A theory of pitch coding (effective roughly between 180-600 Hz) proposing that when a single neuron cannot fire fast enough to match a high frequency, a population of neurons can collectively 'take turns' firing so that the combined output matches the stimulus frequency, even though no single neuron fires that fast alone." },
      { term: "Place Theory", def: "A theory of pitch coding proposing that different physical locations along the organ of Corti are tuned to respond to different frequencies, together accounting for the ability to hear frequencies across the full range up to about 20,000 Hz." },
      { term: "Cross-Fiber (Population) Coding", def: "The general sensory coding principle, seen across multiple sensory systems (not just hearing), in which a single receptor's response is ambiguous on its own, but the combined pattern of activity across a whole population of receptors conveys clear, unambiguous information." },
      { term: "Refractory Period", def: "The brief recovery time after a neuron fires during which it cannot fire again; this caps the maximum firing rate of any single neuron and is the reason frequency theory fails to explain coding of higher-pitched sounds." },
      { term: "Shearing Motion (Organ of Corti)", def: "The relative sliding motion that occurs between the basilar membrane and tectorial membrane as the cochlea vibrates, since they move slightly out of phase with each other; this shearing bends the hair cell cilia and triggers transduction." },
      { term: "Sound Localization (Pinna Cue)", def: "The process of determining where a sound is coming from, assisted by comparing differences in how sound arrives at the two pinnae (external ears) on either side of the head." },
      { term: "Concert A (440 Hz)", def: "A commonly used reference musical pitch at 440 Hz, used as an example to illustrate how the same named note sounds different across instruments due to differing harmonics (timbre)." },
      { term: "Oscillation (Cycle)", def: "One complete up-and-down pass of a sound pressure wave; the number of oscillations occurring in one second defines the sound's frequency in Hertz." },
      { term: "Sensory Transduction (Auditory)", def: "The general process, paralleling transduction in vision, by which the cochlea's hair cells convert physical sound energy (vibration) into electrochemical neural signals that the brain can interpret." },
      { term: "Sound Pressure Wave", def: "The physical disturbance of air molecules that constitutes sound, characterized by its frequency (rate of oscillation) and amplitude (size of the pressure variation), which the ear captures and converts into perception." }
    ]
  },

  "lecture15-psyc2200": {
    title: "Lecture 15",
    subtitle: "Auditory pathways, sound localization & the vestibular system",
    terms: [
      { term: "Pinna", def: "The visible, external flap of the ear that collects sound waves and funnels them into the ear canal." },
      { term: "External Auditory Meatus", def: "The ear canal that channels sound from the pinna down to the eardrum." },
      { term: "Tympanic Membrane (Eardrum)", def: "A thin membrane that vibrates in response to incoming sound pressure waves, transmitting that vibration to the middle ear bones (ossicles)." },
      { term: "Ossicles", def: "The three tiny bones of the middle ear that mechanically link the eardrum to the oval window, amplifying vibrations as sound travels inward." },
      { term: "Oval Window", def: "The membrane-covered opening connecting the middle ear ossicles to the cochlea; its vibration sets the fluid inside the cochlea into motion." },
      { term: "Cochlea", def: "The spiral, fluid-filled structure of the inner ear that converts mechanical sound vibrations into neural signals." },
      { term: "Scala Vestibuli", def: "The uppermost of the cochlea's three fluid-filled compartments, which receives vibration from the oval window." },
      { term: "Scala Tympani", def: "The lowest of the cochlea's three fluid-filled compartments, running parallel to the scala vestibuli." },
      { term: "Scala Media", def: "The middle fluid-filled compartment of the cochlea that houses the organ of Corti, the actual sensory apparatus for hearing." },
      { term: "Organ of Corti", def: "The sensory structure sitting on the basilar membrane inside the scala media that contains the hair cells responsible for transducing sound into neural activity." },
      { term: "Basilar Membrane", def: "The membrane within the cochlea on which the hair cells of the organ of Corti sit; its vibration pattern varies with sound frequency." },
      { term: "Tectorial Membrane", def: "A gelatinous membrane above the organ of Corti that is attached at only one end, allowing it to wobble and brush against the hair cells' cilia as the basilar membrane vibrates." },
      { term: "Cochlear Hair Cells", def: "Sensory receptor cells in the organ of Corti with tiny hair-like cilia on top; mechanical deflection of these cilia against the tectorial membrane triggers the neural signal for hearing." },
      { term: "Cilia (Stereocilia)", def: "The small, graduated hair-like projections on top of hair cells that are arranged from short to tall and are mechanically deflected to initiate transduction." },
      { term: "Tip Links", def: "Tiny protein filaments connecting the tip of one stereocilium to the side of its taller neighbor; stretching these links mechanically pulls open nearby ion channels." },
      { term: "Mechanotransduction (Auditory)", def: "The process by which mechanical bending of hair cell cilia opens ion channels, allowing sodium to flow in and trigger an action potential, converting sound vibration into a neural signal." },
      { term: "8th Cranial Nerve (Vestibulocochlear Nerve)", def: "The cranial nerve that carries both auditory signals from the cochlea and balance signals from the vestibular organs into the brainstem." },
      { term: "Cochlear Nucleus", def: "The first brainstem structure where auditory nerve fibers synapse; it straddles the border of the medulla and pons, and damage here is the only site that can cause complete deafness in one ear." },
      { term: "Tonotopic Organization", def: "A spatial arrangement of neurons according to the sound frequency they respond best to, seen in the cochlear nucleus and maintained throughout the auditory pathway up to cortex." },
      { term: "Cat Cochlear Nucleus Recording Experiment", def: "A classic electrophysiology study in which researchers recorded from individual cochlear nucleus neurons while playing tones across frequencies, discovering that each cell has a preferred (best) frequency and that these preferences are organized systematically from high to low across the nucleus." },
      { term: "Map of Auditory Space", def: "A two-dimensional representation in auditory brain structures where one axis encodes frequency and the other encodes intensity (loudness), so any point carries information about both pitch and volume." },
      { term: "Ascending Auditory Pathway", def: "The serial chain of relay stations carrying sound information from the ear to the cortex: cochlea to 8th nerve to cochlear nucleus to brainstem auditory nuclei to inferior colliculus to medial geniculate nucleus to primary auditory cortex." },
      { term: "Brainstem Auditory Nuclei (Superior Olivary Nuclei)", def: "A group of brainstem nuclei (sometimes called lateral and medial olivary nuclei) that receive input from the cochlear nucleus and compute differences between the two ears to help localize sound in space." },
      { term: "Inferior Colliculus", def: "A midbrain structure that is an obligatory relay station for all ascending auditory information on its way to the thalamus; functionally parallel to the superior colliculus in the visual system but dedicated to sound." },
      { term: "Superior Colliculus (Auditory Context)", def: "A midbrain structure involved in coordinating visual information and orienting responses, discussed here as the auditory system's structural counterpart to the inferior colliculus." },
      { term: "Medial Geniculate Nucleus", def: "The thalamic relay nucleus for the auditory system, analogous to the lateral geniculate nucleus for vision; it receives input from the inferior colliculus and projects to primary auditory cortex." },
      { term: "Primary Auditory Cortex (Brodmann Area 41)", def: "The first cortical area to receive auditory information from the thalamus, located in the temporal lobe; damage or stimulation here relates to basic processing of sound." },
      { term: "Secondary/Tertiary Auditory Cortex (Association Cortex)", def: "Higher-order cortical areas beyond primary auditory cortex that process more complex aspects of sound, such as meaning, memory, and emotional content, recruiting progressively more cortical regions." },
      { term: "Conduction Deafness", def: "Hearing loss caused by a failure of sound to mechanically conduct from the eardrum to the oval window, often due to problems with the ossicles or chronic infections degrading the middle ear bones." },
      { term: "8th Nerve (Sensorineural) Deafness", def: "Hearing loss caused by damage to the cochlea or the 8th cranial nerve itself, resulting in an inability to hear in one ear." },
      { term: "Functional Neuroanatomy (Auditory)", def: "The principle that damage at different points along a sensory pathway produces different, predictable patterns of sensory loss, allowing clinicians to localize lesions based on symptoms." },
      { term: "Interaural Time Difference", def: "A sound localization cue based on the fact that a sound reaches the closer ear a few milliseconds before the farther ear; specialized brainstem neurons detect which ear fired first." },
      { term: "Interaural Phase Difference", def: "A sound localization cue used for ongoing (not just onset) sounds, where neurons compare whether the two ears are receiving sound waves at the same point in their cycle (in phase) or opposite points (out of phase); effective mainly below about 1500 Hz." },
      { term: "Interaural Intensity (Loudness) Difference", def: "A sound localization cue based on the head creating an acoustic shadow, making a sound louder in the ear closer to the source; most effective for higher frequencies (roughly 3-4 kHz and above)." },
      { term: "Sound Localization", def: "The brain's ability to determine the spatial origin of a sound using complementary cues: interaural time differences, phase differences, and intensity differences, each most effective in a different frequency range." },
      { term: "Orienting Response (Auditory)", def: "The reflexive turning of the head or body toward a sound source, driven by brainstem circuits using timing and phase cues, continuing until the signal is equally strong in both ears." },
      { term: "Axon Caliber and Myelination in Auditory Timing", def: "The precise calibration of axon diameter and myelination in auditory brainstem circuits, which fine-tunes conduction velocity so that timing differences between the two ears can be accurately measured." },
      { term: "Penfield's Cortical Stimulation Experiments", def: "Wilder Penfield's studies in which he electrically stimulated regions of the brain in awake patients and had them report their sensations; stimulating auditory cortex produced not simple tones but complex experiences like entire remembered songs with emotional content." },
      { term: "No Parallel Pathways in Audition", def: "The observation that, unlike vision (which can route from the retina to either the lateral geniculate nucleus or the superior colliculus), the auditory system has a single obligatory serial route from cochlea to cortex with no alternate parallel pathway." },
      { term: "Vestibular System", def: "The sensory system responsible for balance and spatial orientation, housed in the inner ear alongside the cochlea, consisting of the semicircular canals and the otolith organs." },
      { term: "Semicircular Canals", def: "Three fluid-filled, looped structures in each inner ear, oriented along the X, Y, and Z axes, that detect rotational (angular) movement of the head." },
      { term: "Vestibular Hair Cells", def: "Hair cells within the vestibular organs whose cilia project into a gel-like fluid; movement of that fluid bends the cilia and triggers depolarization or hyperpolarization depending on the direction of bending." },
      { term: "Bidirectional Angular Accelerometers", def: "The functional description of the semicircular canals: they detect both the direction and the speed (acceleration) of rotational head movement in each of three planes." },
      { term: "Direction Coding via Hyperpolarization/Depolarization", def: "The mechanism by which vestibular hair cells signal movement direction: bending cilia one way causes depolarization, while bending the opposite way causes hyperpolarization, giving the brain a directional code." },
      { term: "Anterior, Posterior, and Lateral Semicircular Canals", def: "The three named semicircular canals in each ear, each oriented in a different plane so that together they can detect head rotation in any direction." },
      { term: "Otolith Organs", def: "The utricle and saccule, vestibular structures that detect linear acceleration and the head's orientation relative to gravity, as opposed to the rotational sensing of the semicircular canals." },
      { term: "Utricle", def: "An otolith organ oriented along one spatial plane that, along with the saccule, uses tiny crystals resting on hair cells to detect head position relative to gravity and linear acceleration." },
      { term: "Saccule", def: "An otolith organ oriented along a plane perpendicular to the utricle that works together with it to detect gravity and linear movement in multiple directions." },
      { term: "Otoconia (Otolith Crystals)", def: "Tiny calcium carbonate crystals, produced naturally by the body, that rest on top of the hair cells in the utricle and saccule and shift with gravity to press on or release the hair cell cilia." },
      { term: "Gravity and Linear Acceleration Detection", def: "The function of the otolith organs: as the head tilts or accelerates linearly, the weight of the otoconia shifts and compresses different hair cells, informing the brain of head position and movement." }
    ]
  },

  "lecture16-psyc2200": {
    title: "Lecture 16",
    subtitle: "Taste, smell & the somatosensory system",
    terms: [
      { term: "Chemical Senses", def: "Taste and smell are called chemical senses because their receptors detect molecules dissolved in saliva (taste) or floating in and dissolved within mucus (smell), rather than light or sound energy." },
      { term: "Taste Bud Map Myth", def: "The commonly taught idea that different regions of the tongue are each responsible for only one taste (sweet, sour, etc.) is false; all areas of the tongue can detect all five tastes, though receptor density may vary slightly by region." },
      { term: "Papillae", def: "Small bump-like structures on the tongue (and some other areas) that house taste buds; there are three basic types, with the mushroom-shaped fungiform papillae being the most visibly obvious." },
      { term: "Fungiform Papillae", def: "Mushroom-shaped papillae on the tongue that typically contain only one to five taste buds each, compared to papillae types that can hold hundreds." },
      { term: "Taste Bud", def: "A garlic-clove-shaped cluster of roughly 100 cells located within papillae, containing taste (receptor) cells, supporting cells, and basal stem cells, with a small opening called the taste pore at its tip." },
      { term: "Taste Pore", def: "The tiny opening at the top of a taste bud through which dissolved chemicals from food enter and contact the microvilli of taste cells." },
      { term: "Taste Cell (Gustatory Receptor Cell)", def: "The receptor cell within a taste bud that extends microvilli into the taste pore to detect dissolved chemicals; it is not technically a neuron but can become electrically active and release neurotransmitter onto gustatory sensory neurons." },
      { term: "Basal Cell (Taste Bud Stem Cell)", def: "A stem cell located at the base of the taste bud that continually regenerates taste cells, which are replaced roughly every 10 days." },
      { term: "Gustatory Sensory Neuron", def: "The sensory neuron that synapses with taste cells at the base of the taste bud and carries taste information via cranial nerves toward the brainstem." },
      { term: "Cranial Nerves VII, IX, and X (Taste)", def: "The facial, glossopharyngeal, and vagus nerves, which carry gustatory (taste) information from different regions of the mouth and throat into the brainstem." },
      { term: "Cranial Nerve I (Olfactory Nerve)", def: "The nerve that carries smell information from olfactory sensory neurons in the nasal epithelium directly into the rostral-most part of the brain (the telencephalon/frontal lobe region)." },
      { term: "Nucleus of the Solitary Tract", def: "A structure in the medulla (brainstem) where incoming taste signals from cranial nerves VII, IX, and X first synapse before being relayed onward, typically to the thalamus in primates." },
      { term: "Gustatory Cortex", def: "The primary cortical area for processing taste, located in the parietal lobe close to the face region of the somatosensory cortex; it receives input relayed from the thalamus." },
      { term: "Five Basic Tastes", def: "The five taste qualities detectable by human taste cells: salty, sour, bitter, umami (savory), and sweet." },
      { term: "Umami", def: "The savory taste quality associated with amino acids such as glutamate, commonly linked to MSG and found naturally in foods like broths and some Asian cuisines." },
      { term: "Ionotropic Taste Receptors", def: "Receptors used by salty and sour taste cells that work directly through ion channels, allowing ions like sodium or hydrogen to create an electrical signal without a second messenger." },
      { term: "Metabotropic Taste Receptors", def: "Receptors used by bitter, umami, and sweet taste cells that rely on G protein-coupled receptors and second messenger systems to activate the cell after a ligand binds." },
      { term: "G Protein-Coupled Receptor (Taste)", def: "A type of metabotropic receptor on the outside of taste cells that binds a taste ligand (e.g., a bitter or sweet molecule) and triggers an internal signaling cascade, sometimes opening ion channels indirectly." },
      { term: "Neurogastronomy", def: "A subfield of neuroscience studying how taste, smell, and somatosensation combine to produce the integrated perceptual experience known as flavor." },
      { term: "Flavor", def: "The combined perceptual experience created by the simultaneous integration of taste, smell, and somatosensory information while eating, which is why food seems bland when the sense of smell is blocked." },
      { term: "Olfactory System (Smell)", def: "The chemical sensory system that detects airborne odorant molecules once they dissolve in nasal mucus; humans have roughly 300 different olfactory receptor types, allowing discrimination of millions of distinct smells." },
      { term: "Olfactory Epithelium", def: "The specialized tissue lining part of the nasal cavity containing olfactory sensory neurons, their cilia, supporting cells, and basal stem cells, all covered in a layer of mucus that dissolves airborne odorants." },
      { term: "Olfactory Sensory Neuron", def: "A neuron in the nasal epithelium with cilia extending into the mucus layer that can bind odorant molecules and generate an action potential; each neuron expresses only one type of odorant receptor." },
      { term: "Cilia (Olfactory)", def: "Hair-like extensions at the end of an olfactory sensory neuron's dendrite that sit in the nasal mucus and contain the receptor proteins and transduction machinery needed to detect odorants and generate a signal." },
      { term: "Cribriform Plate", def: "A perforated bone at the base of the skull through which the axons of olfactory sensory neurons (cranial nerve I) pass on their way from the nasal cavity into the olfactory bulb." },
      { term: "Olfactory Bulb", def: "A paired brain structure located just beneath the ventral frontal lobe where olfactory sensory neuron axons first synapse (within glomeruli) on the same side as the nostril they entered (ipsilaterally)." },
      { term: "Glomerulus (Glomeruli)", def: "Spherical synaptic structures in the olfactory bulb where thousands of olfactory sensory neurons expressing the same receptor type converge and synapse, sorting scattered receptor signals by odorant type, similar to convergence patterns seen in the retina or cochlear nucleus." },
      { term: "Linda Buck", def: "A neuroscientist who, along with her collaborator Richard Axel, won the Nobel Prize for discovering the large family of olfactory receptor genes (over 300 in humans) and how olfactory receptor cells detect odors." },
      { term: "Richard Axel", def: "A neuroscientist who co-discovered, with Linda Buck, the olfactory receptor gene family, work for which they shared the Nobel Prize in Physiology or Medicine." },
      { term: "Olfactory Receptor Diversity", def: "Humans possess about 300 different olfactory receptor genes (the largest gene family in the human genome), while some animals like elephants have roughly 2,000, giving them a much greater capacity to discriminate smells." },
      { term: "Entorhinal Cortex", def: "A brain region that receives olfactory bulb output and provides a direct link to the hippocampus, helping explain why smells are especially effective at triggering memories." },
      { term: "Piriform Cortex", def: "A region in the frontal lobe between the insula and temporal lobe that serves as the first major cortical processing area for smell information arriving from the olfactory bulb." },
      { term: "Olfactory Projections to Amygdala and Hypothalamus", def: "Collateral pathways carrying smell information to the amygdala (for emotional/fear or reward associations) and hypothalamus (for drives such as hunger), explaining why odors can trigger strong emotional or motivational responses." },
      { term: "Pheromone", def: "A chemical signal, often undetectable consciously, that is released by one individual and can influence the physiology or behavior of another individual of the same species." },
      { term: "Apocrine Glands", def: "Specialized sweat glands located mainly near the sex organs and armpits, found at the base of hair follicles, that secrete compounds onto the skin surface and are thought to produce human body-odor pheromone-like signals; humans have more of these glands than any other ape." },
      { term: "White T-Shirt Experiment", def: "A behavioral study in which people wear a plain T-shirt for 24 hours and others then smell it; results show people can judge better than chance whether the wearer was male or female, whether it was their own shirt, whether a relative wore it, and even mothers can identify their own infant's shirt by scent alone." },
      { term: "Ovulation and Scent Preference", def: "Studies show that women's preferences for the scent of T-shirts shift with their menstrual cycle: during ovulation they rate non-relatives' scents as more pleasant, while during non-ovulatory periods they rate family members' scents as more pleasant, suggesting an unconscious role for smell in mate selection." },
      { term: "Anosmia", def: "The inability to smell, the olfactory equivalent of blindness or deafness; it is linked to reduced quality of life and increased depression, and became widely discussed as a common complication of COVID-19." },
      { term: "Ageusia", def: "The inability to taste, a relatively rare condition usually caused by brain injury rather than occurring on its own." },
      { term: "Somatosensory System", def: "The sensory system responsible for detecting touch, temperature, pain, body position, and internal bodily states, divided into exteroceptive, interoceptive, and proprioceptive modalities." },
      { term: "Exteroceptors", def: "Somatosensory receptors that provide information about the external world and the surface of the body, including mechanoreception, thermoreception, and nociception." },
      { term: "Interoceptors", def: "Somatosensory receptors located in the viscera and gut that provide information about the internal physiological state of the body." },
      { term: "Proprioceptors", def: "Receptors, including muscle spindles and Golgi tendon organs, that detect muscle stretch and tendon tension to inform the brain about the position and movement of the body in space." },
      { term: "Mechanoreception", def: "The sensory modality responsible for detecting mechanical disturbances such as pressure, vibration, and light or deep touch through physical displacement of specialized receptors in the skin." },
      { term: "Thermoreception", def: "The sensory modality responsible for detecting temperature, allowing the body to sense whether something is hot or cold." },
      { term: "Nociception", def: "The formal term for the sensory detection of pain, which is further divided into categories such as sharp and dull pain that are carried by different types of receptors and fibers." },
      { term: "Meissner's Corpuscle", def: "A mechanoreceptor located near the skin surface that is particularly sensitive to light touch and changes in texture." },
      { term: "Pacinian Corpuscle", def: "A deep-lying, layered mechanoreceptor that is especially sensitive to vibration and deep pressure." },
      { term: "Ruffini Ending", def: "A mechanoreceptor in the skin that responds to sustained pressure and skin stretch." },
      { term: "Muscle Spindle", def: "A proprioceptive receptor embedded within muscle fibers that detects changes in muscle length and the speed of stretch, sending this information to the spinal cord." },
      { term: "Golgi Tendon Organ", def: "A proprioceptive receptor located in tendons that detects the amount of tension or force generated when a muscle contracts." },
      { term: "Dorsal Root Ganglia", def: "Clusters of sensory neuron cell bodies located on the dorsal (back) side of the spinal cord, where the cell bodies of somatosensory afferent neurons reside before their axons enter the spinal cord." },
      { term: "Discriminative Touch Pathway (Dorsal Column-Medial Lemniscal Pathway)", def: "A somatosensory pathway carrying fine touch information (pressure, texture, precise location) that travels ipsilaterally up the spinal cord and only crosses to the opposite side once it reaches the brainstem, before continuing to the thalamus and somatosensory cortex." },
      { term: "Spinothalamic Tract (Anterolateral Pathway)", def: "A somatosensory pathway carrying pain, temperature, and tickle information that crosses to the opposite side of the spinal cord immediately upon entry (at the level it enters), then travels up the anterolateral spinal cord to the thalamus." },
      { term: "Decussation (Somatosensory)", def: "The crossing of sensory pathways from one side of the body to the other; discriminative touch decussates late (in the brainstem) while pain and temperature information decussates immediately in the spinal cord, which has clinical implications for localizing spinal cord injuries." },
      { term: "Somatosensory Cortex", def: "The primary cortical region in the parietal lobe, just posterior to the central sulcus, that processes touch, pain, temperature, and proprioceptive information from the body." },
      { term: "Sensory Homunculus", def: "A distorted map of the body represented across the somatosensory cortex, where more sensitive body regions (like the hands and face) are allotted disproportionately larger areas of cortical tissue than less sensitive regions." },
      { term: "Central Sulcus", def: "The groove on the cortical surface separating the frontal lobe (motor cortex) from the parietal lobe (somatosensory cortex), marking the anatomical boundary between sensory and motor processing regions." }
    ]
  }
};

